package com.wizzadrds.theworldremembers.knowledge; import com.mojang.serialization.Codec; import net.minecraft.resources.Identifier; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import java.util.*; public final class KnowledgeManager extends SavedData{private final Map<UUID,List<KnowledgeFact>> facts=new HashMap<>();private static final Codec<KnowledgeManager>C=Codec.unboundedMap(com.mojang.serialization.Codec.STRING.xmap(UUID::fromString,UUID::toString),KnowledgeFact.CODEC.listOf()).xmap(m->{var x=new KnowledgeManager();x.facts.putAll(m);return x;},x->x.facts);private static final SavedDataType<KnowledgeManager>TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","knowledge"),KnowledgeManager::new,C,null);public static KnowledgeManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new KnowledgeManager():l.getDataStorage().computeIfAbsent(TYPE);}public boolean addDirect(UUID npc,String eventId,String type,UUID subject,long tick){var list=facts.computeIfAbsent(npc,k->new ArrayList<>());if(list.stream().anyMatch(f->f.eventId().equals(eventId)))return false;list.add(new KnowledgeFact(eventId,type,subject,null,tick,tick,1.0,KnowledgeOrigin.DIRECT));setDirty();return true;}public boolean report(UUID listener,UUID speaker,KnowledgeFact source,long tick){var list=facts.computeIfAbsent(listener,k->new ArrayList<>());if(list.stream().anyMatch(f->f.eventId().equals(source.eventId())&&f.origin()==KnowledgeOrigin.DIRECT))return false;var origin=source.origin()==KnowledgeOrigin.DIRECT?KnowledgeOrigin.REPORTED:KnowledgeOrigin.RUMORED;double confidence=Math.max(0.05,source.confidence()*0.75);var existing=list.stream().filter(f->f.eventId().equals(source.eventId())).findFirst();if(existing.isPresent()&&existing.get().confidence()>=confidence)return false;list.removeIf(f->f.eventId().equals(source.eventId())&&f.origin()!=KnowledgeOrigin.DIRECT);list.add(new KnowledgeFact(source.eventId(),source.type(),source.subject(),speaker,source.observedTick(),tick,confidence,origin));setDirty();return true;}public void degrade(long now,long ticksPerStep){if(ticksPerStep<=0)return;for(var list:facts.values())for(int i=0;i<list.size();i++){var f=list.get(i);if(f.origin()==KnowledgeOrigin.DIRECT)continue;long steps=Math.max(0,(now-f.acquiredTick())/ticksPerStep);double c=Math.max(0.05,f.confidence()*Math.pow(0.98,steps));list.set(i,new KnowledgeFact(f.eventId(),f.type(),f.subject(),f.source(),f.observedTick(),f.acquiredTick(),c,f.origin));}setDirty();}public List<KnowledgeFact> factsOf(UUID npc){return List.copyOf(facts.getOrDefault(npc,List.of()));}}